/**
 * PWA Push Notification Utility
 *
 * Browser side of web push for the mobile PWA: permission, service worker
 * lookup and `PushManager` subscriptions. Talking to the API (storing and
 * removing subscriptions) lives in `hooks/usePushNotifications.ts`.
 *
 * The service worker is generated by next-pwa at build time and is disabled in
 * development (see next.config.ts), so in `next dev` there is no worker and
 * subscribing reports `no-service-worker`.
 */

/**
 * Type definition for push subscription that matches backend expectations
 */
export interface PushSubscriptionData {
  endpoint: string;
  keys: {
    p256dh: string;
    auth: string;
  };
}

/**
 * Why a subscription attempt did not succeed.
 * - unsupported: the browser has no service worker / Push API / Notification API
 * - not-configured: no VAPID public key is available
 * - no-service-worker: the app's service worker is not registered (e.g. development)
 * - denied: the user (or the browser) blocked notifications
 * - dismissed: the permission prompt was closed without an answer
 * - error: anything else (see `error`)
 */
export type PushFailureReason =
  | 'unsupported'
  | 'not-configured'
  | 'no-service-worker'
  | 'denied'
  | 'dismissed'
  | 'error';

/**
 * Result of a subscription attempt
 */
export interface SubscriptionResult {
  success: boolean;
  subscription?: PushSubscriptionData;
  reason?: PushFailureReason;
  error?: string;
}

/** How long to wait for the service worker before concluding there is none. */
const SERVICE_WORKER_TIMEOUT_MS = 4000;

/**
 * Check if the browser supports push notifications
 */
export function isPushNotificationSupported(): boolean {
  if (typeof window === 'undefined') {
    return false;
  }

  return 'serviceWorker' in navigator && 'PushManager' in window && 'Notification' in window;
}

/**
 * Get the current notification permission status
 */
export function getNotificationPermission(): NotificationPermission {
  if (typeof window === 'undefined' || !('Notification' in window)) {
    return 'default';
  }

  return Notification.permission;
}

/**
 * Request notification permission from the user
 */
export async function requestNotificationPermission(): Promise<NotificationPermission> {
  if (!isPushNotificationSupported()) {
    throw new Error('Push notifications are not supported in this browser');
  }

  if (getNotificationPermission() === 'granted') {
    return 'granted';
  }

  try {
    const permission = await Notification.requestPermission();
    return permission;
  } catch (error) {
    console.error('Error requesting notification permission:', error);
    throw new Error('Failed to request notification permission');
  }
}

/**
 * Get the app's active service worker registration, or null when there is
 * none. Unlike `navigator.serviceWorker.ready` this never waits forever when
 * no worker is registered.
 */
async function getServiceWorkerRegistration(
  waitMs: number = SERVICE_WORKER_TIMEOUT_MS,
): Promise<ServiceWorkerRegistration | null> {
  if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) {
    return null;
  }

  try {
    const existing = await navigator.serviceWorker.getRegistration();
    if (existing?.active) return existing;
    if (waitMs <= 0) return null;

    // Registered but still installing (first visit), or about to be registered
    return await Promise.race([
      navigator.serviceWorker.ready,
      new Promise<null>((resolve) => setTimeout(() => resolve(null), waitMs)),
    ]);
  } catch (error) {
    console.error('Error getting service worker registration:', error);
    return null;
  }
}

/**
 * Convert a base64url string to bytes (VAPID application server key)
 */
function urlBase64ToUint8Array(base64String: string): Uint8Array<ArrayBuffer> {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');

  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);

  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i);
  }

  return outputArray;
}

/** True when an existing subscription was created with the given application server key. */
function usesApplicationServerKey(subscription: PushSubscription, key: Uint8Array): boolean {
  const current = subscription.options?.applicationServerKey;
  if (!current) return false;
  const bytes = new Uint8Array(current);
  return bytes.length === key.length && bytes.every((byte, i) => byte === key[i]);
}

/**
 * Convert PushSubscription to the format expected by the backend
 */
function convertSubscriptionToData(subscription: PushSubscription): PushSubscriptionData {
  const subscriptionJson = subscription.toJSON();

  if (!subscriptionJson.endpoint || !subscriptionJson.keys) {
    throw new Error('Invalid subscription format');
  }

  return {
    endpoint: subscriptionJson.endpoint,
    keys: {
      p256dh: subscriptionJson.keys.p256dh || '',
      auth: subscriptionJson.keys.auth || '',
    },
  };
}

/**
 * Subscribe this browser to push notifications.
 *
 * Asks for permission if needed. An existing subscription made with the same
 * VAPID key is reused (so the endpoint stays stable); one made with a
 * different key is replaced.
 *
 * @param vapidPublicKey - VAPID public key; defaults to NEXT_PUBLIC_VAPID_PUBLIC_KEY
 */
export async function subscribeToPushNotifications(
  vapidPublicKey?: string | null,
): Promise<SubscriptionResult> {
  try {
    if (!isPushNotificationSupported()) {
      return {
        success: false,
        reason: 'unsupported',
        error: 'Push notifications are not supported in this browser',
      };
    }

    const publicKey = vapidPublicKey || process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY;

    if (!publicKey) {
      return {
        success: false,
        reason: 'not-configured',
        error: 'VAPID public key is not configured',
      };
    }

    if (getNotificationPermission() === 'denied') {
      return { success: false, reason: 'denied', error: 'Notification permission denied' };
    }

    // Look for the worker before prompting: no point asking if it cannot work
    const registration = await getServiceWorkerRegistration();
    if (!registration) {
      return {
        success: false,
        reason: 'no-service-worker',
        error: 'Service worker is not registered',
      };
    }

    const permission = await requestNotificationPermission();

    if (permission !== 'granted') {
      return {
        success: false,
        reason: permission === 'denied' ? 'denied' : 'dismissed',
        error: `Notification permission ${permission}`,
      };
    }

    const applicationServerKey = urlBase64ToUint8Array(publicKey);
    let subscription = await registration.pushManager.getSubscription();

    // A subscription bound to another VAPID key cannot receive our pushes
    if (subscription && !usesApplicationServerKey(subscription, applicationServerKey)) {
      await subscription.unsubscribe();
      subscription = null;
    }

    if (!subscription) {
      subscription = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey,
      });
    }

    return {
      success: true,
      subscription: convertSubscriptionToData(subscription),
    };
  } catch (error) {
    console.error('Error subscribing to push notifications:', error);
    return {
      success: false,
      reason: 'error',
      error: error instanceof Error ? error.message : 'Failed to subscribe to push notifications',
    };
  }
}

/**
 * Get the current push subscription (does not wait for a service worker that
 * is still installing)
 *
 * @param vapidPublicKey - When given, a subscription made with a different key counts as none
 * @returns The current subscription data or null if not subscribed
 */
export async function getCurrentPushSubscription(
  vapidPublicKey?: string | null,
): Promise<PushSubscriptionData | null> {
  try {
    if (!isPushNotificationSupported()) {
      return null;
    }

    const registration = await getServiceWorkerRegistration(0);
    const subscription = await registration?.pushManager.getSubscription();

    if (!subscription) {
      return null;
    }

    // Made with another VAPID key (keys were rotated): our pushes cannot reach it
    if (
      vapidPublicKey &&
      !usesApplicationServerKey(subscription, urlBase64ToUint8Array(vapidPublicKey))
    ) {
      return null;
    }

    return convertSubscriptionToData(subscription);
  } catch (error) {
    console.error('Error getting current push subscription:', error);
    return null;
  }
}

/**
 * Unsubscribe from push notifications
 *
 * @returns true if successfully unsubscribed, false otherwise
 */
export async function unsubscribeFromPushNotifications(): Promise<boolean> {
  try {
    if (!isPushNotificationSupported()) {
      return false;
    }

    const registration = await getServiceWorkerRegistration();
    const subscription = await registration?.pushManager.getSubscription();

    if (!subscription) {
      return true; // Already unsubscribed
    }

    const success = await subscription.unsubscribe();
    return success;
  } catch (error) {
    console.error('Error unsubscribing from push notifications:', error);
    return false;
  }
}

/**
 * Check if the user is currently subscribed to push notifications
 *
 * @returns true if subscribed, false otherwise
 */
export async function isSubscribedToPushNotifications(): Promise<boolean> {
  return (await getCurrentPushSubscription()) !== null;
}

/**
 * Request notification permission and subscribe to push notifications in one step
 * This is a convenience function that combines permission request and subscription
 *
 * @param vapidPublicKey - Optional VAPID public key (uses env var if not provided)
 * @returns SubscriptionResult with the subscription data or error
 */
export async function setupPushNotifications(
  vapidPublicKey?: string | null,
): Promise<SubscriptionResult> {
  return subscribeToPushNotifications(vapidPublicKey);
}
